/**
 * USC-Formatted DOCX Report Builder (A4, Times New Roman 12pt, 1.5 spacing, 1-inch margins).
 * Reads `report/src/report_data.json` generated by `plans/src/report_build.py` and writes
 * `report/Group1_Proposed_Structured_Cabling_Plan.docx` with automatic Word TOC, LOF, LOT fields.
 */
const fs = require("fs");
const path = require("path");

// Read-only import of docx package installed in sibling Final Proj/report/node_modules
const docx = require(path.join(
  "D:/Junior Year/first sem/COMPUTER NETWORKS AND SECURITY/Final Proj/report/node_modules/docx"
));

const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, WidthType, BorderStyle, ShadingType,
  PageBreak, ImageRun, Header, Footer, PageNumber, SimpleField,
  TableOfContents, VerticalAlign, convertInchesToTwip,
} = docx;

const DATA_PATH = path.join("D:/Junior Year/first sem/COMPUTER NETWORKS AND SECURITY/RJ esports/report/src/report_data.json");
const data = JSON.parse(fs.readFileSync(DATA_PATH, "utf8"));

const FONT = "Times New Roman";
const NAVY = "1B2A4A";
const LIGHT_BG = "F1F5F9";
const BORDER_COL = "94A3B8";
const CODE_BG = "F8FAFC";

const thinBorder = { style: BorderStyle.SINGLE, size: 4, color: BORDER_COL };
const cellBorders = { top: thinBorder, bottom: thinBorder, left: thinBorder, right: thinBorder };

function pText(text, opts = {}) {
  const runs = [];
  if (opts.boldPrefix) {
    runs.push(new TextRun({ text: opts.boldPrefix, font: FONT, size: opts.size || 24, bold: true, color: opts.color || "000000" }));
  }
  runs.push(new TextRun({
    text: String(text || ""),
    font: opts.font || FONT,
    size: opts.size || 24, // 24 half-points = 12 pt
    bold: !!opts.bold,
    italics: !!opts.italics,
    color: opts.color || "000000",
  }));
  return new Paragraph({
    children: runs,
    alignment: opts.align || AlignmentType.JUSTIFIED,
    spacing: {
      line: opts.line || 360, // 1.5 line spacing
      before: opts.before !== undefined ? opts.before : 0,
      after: opts.after !== undefined ? opts.after : 100,
    },
    indent: opts.hanging ? { left: 720, hanging: 720 } : (opts.leftIndent ? { left: opts.leftIndent } : undefined),
    pageBreakBefore: !!opts.pageBreakBefore,
    keepNext: !!opts.keepNext,
  });
}

function heading1(text, pageBreak = true) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    alignment: AlignmentType.LEFT,
    pageBreakBefore: pageBreak,
    keepNext: true,
    spacing: { before: 120, after: 140, line: 276 },
    children: [new TextRun({ text, font: FONT, size: 28, bold: true, color: NAVY })],
  });
}

function heading2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    alignment: AlignmentType.LEFT,
    keepNext: true,
    spacing: { before: 160, after: 80, line: 276 },
    children: [new TextRun({ text, font: FONT, size: 24, bold: true, color: NAVY })],
  });
}

function captionParagraph(seqType, num, title, above = false) {
  // Word SEQ field enables automatic List of Figures / List of Tables updates!
  return new Paragraph({
    alignment: AlignmentType.CENTER,
    keepNext: above,
    spacing: { before: above ? 120 : 60, after: above ? 60 : 140, line: 240 },
    children: [
      new TextRun({ text: `${seqType} `, font: FONT, size: 20, bold: true, color: NAVY }),
      new SimpleField(`SEQ ${seqType} \\* ARABIC`, String(num)),
      new TextRun({ text: `. ${title}`, font: FONT, size: 20, italics: true, color: "1E293B" }),
    ],
  });
}

function buildTable(tbl) {
  const colCount = tbl.headers.length;
  const colWidths = tbl.widths || Array(colCount).fill(Math.floor(9000 / colCount));
  const fsize = tbl.fontSize || 18; // 9 pt crisp academic tables

  const headerRow = new TableRow({
    tableHeader: true,
    children: tbl.headers.map((h, i) => new TableCell({
      width: { size: colWidths[i], type: WidthType.DXA },
      shading: { type: ShadingType.CLEAR, fill: NAVY },
      borders: cellBorders,
      verticalAlign: VerticalAlign.CENTER,
      margins: { top: 60, bottom: 60, left: 80, right: 80 },
      children: [new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { line: 240, before: 0, after: 0 },
        children: [new TextRun({ text: String(h), font: FONT, size: fsize, bold: true, color: "FFFFFF" })],
      })],
    })),
  });

  const bodyRows = tbl.rows.map((r, rIdx) => {
    const isTotal = tbl.boldLastRow && rIdx === tbl.rows.length - 1;
    const fill = isTotal ? "E2E8F0" : (rIdx % 2 === 1 ? LIGHT_BG : "FFFFFF");
    return new TableRow({
      cantSplit: true,
      children: r.map((val, cIdx) => {
        const alignStr = (tbl.aligns && tbl.aligns[cIdx]) || "left";
        const align = alignStr === "right" ? AlignmentType.RIGHT : (alignStr === "center" ? AlignmentType.CENTER : AlignmentType.LEFT);
        return new TableCell({
          width: { size: colWidths[cIdx], type: WidthType.DXA },
          shading: { type: ShadingType.CLEAR, fill },
          borders: cellBorders,
          verticalAlign: VerticalAlign.CENTER,
          margins: { top: 28, bottom: 28, left: 65, right: 65 },
          children: [new Paragraph({
            alignment: align,
            spacing: { line: 220, before: 0, after: 0 },
            children: [new TextRun({ text: String(val), font: FONT, size: fsize, bold: isTotal || (tbl.boldCol0 && cIdx === 0) })],
          })],
        });
      }),
    });
  });

  const nodes = [];
  if (tbl.caption) {
    nodes.push(captionParagraph("Table", tbl.num, tbl.caption, true));
  }
  nodes.push(new Table({
    width: { size: 9000, type: WidthType.DXA },
    rows: [headerRow, ...bodyRows],
  }));
  nodes.push(new Paragraph({ spacing: { before: 0, after: 100 }, children: [] }));
  return nodes;
}

function getPngSize(filePath) {
  const buf = fs.readFileSync(filePath);
  // PNG IHDR width/height at bytes 16..23
  if (buf.length >= 24 && buf.toString("ascii", 1, 4) === "PNG") {
    return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20) };
  }
  return { w: 1200, h: 800 };
}

function buildFigure(fig) {
  const nodes = [];
  const maxW = fig.widthPx || 595; // ~6.2 inches inside A4 1-in margins
  const maxH = fig.maxHeightPx || 440;

  if (fig.path && fs.existsSync(fig.path)) {
    const dim = getPngSize(fig.path);
    let w = maxW;
    let h = Math.round((dim.h / dim.w) * w);
    if (h > maxH) {
      h = maxH;
      w = Math.round((dim.w / dim.h) * h);
    }
    nodes.push(new Paragraph({
      alignment: AlignmentType.CENTER,
      keepNext: true,
      spacing: { before: 100, after: 40, line: 240 },
      children: [new ImageRun({
        data: fs.readFileSync(fig.path),
        transformation: { width: w, height: h },
      })],
    }));
  } else {
    // Neat dashed placeholder box ONLY for screenshots not yet dropped into report/screenshots/
    const dashed = { style: BorderStyle.DASHED, size: 12, color: "64748B" };
    nodes.push(new Table({
      width: { size: 8800, type: WidthType.DXA },
      rows: [new TableRow({
        children: [new TableCell({
          width: { size: 8800, type: WidthType.DXA },
          shading: { type: ShadingType.CLEAR, fill: "F8FAFC" },
          borders: { top: dashed, bottom: dashed, left: dashed, right: dashed },
          margins: { top: 260, bottom: 260, left: 220, right: 220 },
          children: [
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { line: 260, after: 60 },
              children: [new TextRun({ text: `[SCREENSHOT DROP-IN PLACEHOLDER: ${fig.expectedFile || "image.png"}]`, font: FONT, size: 22, bold: true, color: NAVY })],
            }),
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { line: 240, after: 0 },
              children: [new TextRun({ text: fig.placeholderNote || "Save screenshot into report/screenshots/ and re-run report_build.py to auto-embed.", font: FONT, size: 19, italics: true, color: "475569" })],
            }),
          ],
        })],
      })],
    }));
  }
  nodes.push(captionParagraph("Figure", fig.num, fig.caption, false));
  return nodes;
}

function buildCodeBlock(title, text) {
  const lines = String(text || "").split("\n");
  return [
    new Paragraph({
      keepNext: true,
      spacing: { before: 100, after: 40, line: 240 },
      children: [new TextRun({ text: title, font: FONT, size: 21, bold: true, color: NAVY })],
    }),
    new Table({
      width: { size: 9000, type: WidthType.DXA },
      rows: [new TableRow({
        children: [new TableCell({
          width: { size: 9000, type: WidthType.DXA },
          shading: { type: ShadingType.CLEAR, fill: CODE_BG },
          borders: cellBorders,
          margins: { top: 80, bottom: 80, left: 110, right: 110 },
          children: lines.map(ln => new Paragraph({
            alignment: AlignmentType.LEFT,
            spacing: { line: 210, before: 0, after: 0 },
            children: [new TextRun({ text: ln === "" ? " " : ln, font: "Courier New", size: 16, color: "0F172A" })],
          })),
        })],
      })],
    }),
    new Paragraph({ spacing: { before: 0, after: 80 }, children: [] }),
  ];
}

function renderBlocks(blocks) {
  const out = [];
  for (const b of blocks) {
    if (b.type === "h1") out.push(heading1(b.text, b.pageBreak !== false));
    else if (b.type === "h2") out.push(heading2(b.text));
    else if (b.type === "p") out.push(pText(b.text, b.opts || {}));
    else if (b.type === "bullet") out.push(pText("•  " + b.text, { leftIndent: 360, after: 60, boldPrefix: b.boldPrefix }));
    else if (b.type === "table") out.push(...buildTable(b));
    else if (b.type === "figure") out.push(...buildFigure(b));
    else if (b.type === "code") out.push(...buildCodeBlock(b.title, b.text));
    else if (b.type === "ref") out.push(pText(b.text, { hanging: true, after: 100, line: 360 }));
    else if (b.type === "pagebreak") out.push(new Paragraph({ children: [new PageBreak()] }));
  }
  return out;
}

// --- Build Cover Page Section ---
